commit 9382c5375bb66872cdedb0fd36e68e371fae8721
Author: Martijn van Beurden <mvanb1@gmail.com>
Date:   Wed Feb 22 21:13:08 2023 +0100

    Add checks on re-encoding FLAC

    While decoding from FLAC checks for changes no. of channels, bps
    and sample rate, re-encoding doesn't. A fuzzer found use of
    uninitialized memory because of this. A few checks are added,
    although the user isn't warned on a samplerate change.

diff --git a/src/flac/encode.c b/src/flac/encode.c
index e99b3fd1..920a8410 100644
--- a/src/flac/encode.c
+++ b/src/flac/encode.c
@@ -2567,6 +2567,18 @@ FLAC__StreamDecoderWriteStatus flac_decoder_write_callback(const FLAC__StreamDec
        FLAC__uint64 n = min(data->samples_left_to_process, frame->header.blocksize);
        (void)decoder;

+       /* Do some checks */
+       if(frame->header.channels != e->info.channels) {
+               print_error_with_state(e, "ERROR: number of channels of input changed mid-stream");
+               data->fatal_error = true;
+               return FLAC__STREAM_DECODER_WRITE_STATUS_ABORT;
+       }
+       if(frame->header.bits_per_sample > e->info.bits_per_sample) {
+               print_error_with_state(e, "ERROR: bits-per-sample of input changed mid-stream");
+               data->fatal_error = true;
+               return FLAC__STREAM_DECODER_WRITE_STATUS_ABORT;
+       }
+
        if(!EncoderSession_process(e, buffer, (uint32_t)n)) {
                print_error_with_state(e, "ERROR during encoding");
                data->fatal_error = true;
commit 5f39e88a88f39f7e508dc1fede30a2e0bb486008
Author: Martijn van Beurden <mvanb1@gmail.com>
Date:   Fri Feb 17 07:30:13 2023 +0100

    Fix strlen being used on uninitialized data

diff --git a/src/metaflac/utils.c b/src/metaflac/utils.c
index e3f27601..236fde4e 100644
--- a/src/metaflac/utils.c
+++ b/src/metaflac/utils.c
@@ -76,6 +76,11 @@ void local_strcat(char **dest, const char *source)
        *dest = safe_realloc_add_3op_(*dest, ndest, /*+*/nsource, /*+*/1);
        if(*dest == NULL)
                die("out of memory growing string");
+       /* If ndest == 0, strlen in safe_strncat reads
+        * uninitialized data. To prevent that, set first character
+        * to zero */
+       if(ndest == 0)
+               *dest[0] = 0;
        safe_strncat(*dest, source, outlen);
 }

commit 69cf76c58e797d093cea73b1f8ad1ff55ec2786d
Author: Martijn van Beurden <mvanb1@gmail.com>
Date:   Fri May 20 14:55:43 2022 +0200

    Fix use of undefined value

    The mechanism to improve metadata reading added in 0077d3b overrides
    a FLAC__STREAM_DECODER_ABORTED with
    FLAC__STREAM_DECODER_SEARCH_FOR_FRAME_SYNC causing the decoder to
    overread a buffer into an uninitialized part. A check is added that
    ensures searching for frame sync is only set when the decoder is
    still in a valid state

    Credit: Oss-Fuzz
    Issue: https://bugs.chromium.org/p/oss-fuzz/issues/detail?id=47525

diff --git a/src/libFLAC/stream_decoder.c b/src/libFLAC/stream_decoder.c
index afc3923a..f085e3be 100644
--- a/src/libFLAC/stream_decoder.c
+++ b/src/libFLAC/stream_decoder.c
@@ -1525,7 +1525,8 @@ FLAC__bool read_metadata_(FLAC__StreamDecoder *decoder)
                                 * We cannot know whether the length or the content was
                                 * corrupt, so stop parsing metadata */
                                send_error_to_client_(decoder, FLAC__STREAM_DECODER_ERROR_STATUS_BAD_METADATA);
-                               decoder->protected_->state = FLAC__STREAM_DECODER_SEARCH_FOR_FRAME_SYNC;
+                               if(decoder->protected_->state == FLAC__STREAM_DECODER_READ_METADATA)
+                                       decoder->protected_->state = FLAC__STREAM_DECODER_SEARCH_FOR_FRAME_SYNC;
                                ok = false;
                        }
                        FLAC__bitreader_remove_limit(decoder->private_->input);
